package com.johnny.hotel.pagination;import com.johnny.hotel.exception.BusinessException;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;
@Component @RequiredArgsConstructor public class PaginationSupport{private final PaginationProperties properties;public record Window(int page,int pageSize,int offset,boolean searchMode,int browseLimit){}
 public Window window(Integer page,Integer size,boolean search){int p=page==null?1:page,s=size==null?Math.min(20,properties.getMaxPageSize()):size;if(p<1||s<1||s>properties.getMaxPageSize())throw new BusinessException("page must be positive and pageSize must not exceed "+properties.getMaxPageSize());long offset=(long)(p-1)*s;if(offset>Integer.MAX_VALUE)throw new BusinessException("Pagination offset is too large");return new Window(p,s,(int)offset,search,properties.getBrowseLimit());}
 public <T> PageResult<T> result(Window w,List<T> items,long databaseTotal){long total=w.searchMode()?databaseTotal:Math.min(databaseTotal,w.browseLimit());return PageResult.<T>builder().items(items).page(w.page()).pageSize(w.pageSize()).total(total).hasNext((long)w.offset()+items.size()<total).searchMode(w.searchMode()).build();}
 public int limit(Window w){if(w.searchMode())return w.pageSize();int remaining=w.browseLimit()-w.offset();return Math.max(0,Math.min(w.pageSize(),remaining));}
}
